"""tk011_move.py: выносит именованные узлы верхнего уровня (с комментариями над ними) из dispatch.py в новый модуль."""
import ast, sys
from pathlib import Path
DD = Path(".claude/dispatcher")
disp = DD / "dispatch.py"
src = disp.read_text(encoding="utf-8")
lines = src.splitlines(keepends=True)
tree = ast.parse(src)

def names(n):
    if isinstance(n, (ast.FunctionDef, ast.ClassDef)): return [n.name]
    if isinstance(n, ast.Assign):
        return [m.id for t in n.targets for m in ast.walk(t) if isinstance(m, ast.Name)]
    return []

def span(n):
    lo = n.lineno
    while lo > 1 and lines[lo-2].lstrip().startswith("#"):
        lo -= 1
    return lo, n.end_lineno

def extract(wanted):
    sel = [n for n in tree.body if set(names(n)) & set(wanted)]
    got = {x for n in sel for x in names(n)}
    assert set(wanted) <= got, set(wanted) - got
    sp = [span(n) for n in sel]
    body = "\n\n".join("".join(lines[a-1:b]).rstrip("\n") + "\n" for a, b in sp)
    return sp, body

def apply(sp_all, repl):
    drop = set()
    for a, b in sp_all:
        drop.update(range(a, b+1))
    out = "".join(l for i, l in enumerate(lines, 1) if i not in drop)
    return out
import ast, builtins, sys
from pathlib import Path
p = Path(sys.argv[1]); LO, HI = int(sys.argv[2]), int(sys.argv[3])
src = p.read_text(encoding="utf-8"); lines = src.splitlines()
body = "\n".join(lines[LO-1:HI])
t = ast.parse(body)
defs = set()
for n in t.body:
    if isinstance(n,(ast.FunctionDef,ast.ClassDef)): defs.add(n.name)
    elif isinstance(n,ast.Assign):
        for x in n.targets:
            for m in ast.walk(x):
                if isinstance(m,ast.Name): defs.add(m.id)
load = {n.id for n in ast.walk(t) if isinstance(n,ast.Name) and isinstance(n.ctx,ast.Load)}
store = set()
for n in ast.walk(t):
    if isinstance(n,ast.arg): store.add(n.arg)
    elif isinstance(n,ast.Name) and isinstance(n.ctx,ast.Store): store.add(n.id)
    elif isinstance(n,ast.ExceptHandler) and n.name: store.add(n.name)
    elif isinstance(n,(ast.Import,ast.ImportFrom)):
        for a in n.names: store.add((a.asname or a.name).split(".")[0])
print("DEFS", sorted(defs)); print("FREE", sorted(load-defs-store-set(dir(builtins))))

